package com.ssk.kiosk.integration;
import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class IntegrationConfigurationService {private final IntegrationConfigurationRepository repository;public IntegrationConfigurationService(IntegrationConfigurationRepository r){repository=r;}public List<IntegrationConfiguration> all(){return repository.findAll();}public IntegrationConfiguration required(String key){return repository.findById(key).orElseThrow(()->new IllegalStateException(key+" integration is not configured"));}@Transactional public IntegrationConfiguration update(String key,Map<String,Object> values,String actor){IntegrationConfiguration c=repository.findById(key.toUpperCase(Locale.ROOT)).orElseThrow();Object revision=values.get("rowVersion");if(revision instanceof Number n&&!Objects.equals(c.getRowVersion(),n.longValue()))throw new org.springframework.orm.ObjectOptimisticLockingFailureException(IntegrationConfiguration.class,key);c.setEnabled(Boolean.TRUE.equals(values.get("enabled")));c.setBaseUrl(url(values,"baseUrl"));c.setVerificationPath(endpoint(values,"verificationPath"));c.setApprovalField(fieldPath(values,"approvalField"));c.setApprovalValue(String.valueOf(values.getOrDefault("approvalValue","true")));c.setConnectTimeoutMs(range(values,"connectTimeoutMs",500,60000));c.setReadTimeoutMs(range(values,"readTimeoutMs",500,120000));c.setRetryCount(range(values,"retryCount",0,5));c.setUpdatedAt(Instant.now());c.setUpdatedBy(actor);return repository.save(c);}private String url(Map<String,Object>v,String key){String value=String.valueOf(v.getOrDefault(key,"")).trim();if(!value.isEmpty()&&!value.matches("https://[^\\s]+"))throw new IllegalArgumentException(key+" must be an HTTPS URL");return value;}private String endpoint(Map<String,Object>v,String key){String value=String.valueOf(v.getOrDefault(key,"/verify")).trim();if(!value.matches("/[A-Za-z0-9_./-]*" )||value.contains(".."))throw new IllegalArgumentException(key+" is invalid");return value;}private String fieldPath(Map<String,Object>v,String key){String value=String.valueOf(v.getOrDefault(key,"verified")).trim();if(!value.matches("[A-Za-z0-9_.\\[\\]-]+"))throw new IllegalArgumentException(key+" is invalid");return value;}private int range(Map<String,Object>v,String key,int min,int max){int n=((Number)v.getOrDefault(key,min)).intValue();if(n<min||n>max)throw new IllegalArgumentException(key+" outside permitted range");return n;}}
